#!/usr/bin/env bash
# EterX Agent source installer (Linux/macOS)
#
# End users should normally use the AppImage, .deb, or .dmg generated by the
# Electron packaging scripts. This is the no-Git fallback for source installs.

set -euo pipefail

INSTALL_DIR="${ETERX_DIR:-$HOME/EterX}"
ARCHIVE_URL="${ETERX_ARCHIVE_URL:-https://github.com/harshilsoni5666/EterX-agent-/archive/refs/heads/main.zip}"

status() {
  printf '  \033[0;36m%s\033[0m\n' "$1"
}

has_source_install() {
  [ -f "$1/package.json" ] && [ -f "$1/setup.js" ]
}

ensure_node() {
  if command -v node >/dev/null 2>&1; then
    printf '  \033[0;32mNode.js %s found\033[0m\n' "$(node --version)"
    return
  fi

  status 'Node.js was not found. Installing Node.js 20 with nvm...'
  if ! command -v curl >/dev/null 2>&1; then
    printf '  \033[0;31mcurl is required to bootstrap a source install.\033[0m\n' >&2
    exit 1
  fi
  export NVM_DIR="${NVM_DIR:-$HOME/.nvm}"
  if [ ! -s "$NVM_DIR/nvm.sh" ]; then
    curl -fsSL https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.3/install.sh | bash
  fi
  # shellcheck disable=SC1090
  . "$NVM_DIR/nvm.sh"
  nvm install 20
  nvm use 20
}

install_source_archive() {
  if has_source_install "$INSTALL_DIR"; then
    status "Using existing source installation: $INSTALL_DIR"
    return
  fi

  if ! command -v curl >/dev/null 2>&1 || ! command -v unzip >/dev/null 2>&1; then
    printf '  \033[0;31mSource installation needs curl and unzip. Install them, then run this script again.\033[0m\n' >&2
    exit 1
  fi

  local staging archive source
  staging="$(mktemp -d "${TMPDIR:-/tmp}/eterx-source.XXXXXX")"
  archive="$staging/eterx.zip"
  trap 'rm -rf "$staging"' RETURN

  status 'Downloading the EterX source archive (no Git required)...'
  curl --fail --location --retry 3 "$ARCHIVE_URL" -o "$archive"
  unzip -q "$archive" -d "$staging"
  source="$(find "$staging" -mindepth 1 -maxdepth 1 -type d -exec sh -c '[ -f "$1/package.json" ] && [ -f "$1/setup.js" ] && printf "%s" "$1"' _ {} \; | head -n 1)"
  if [ -z "$source" ]; then
    printf '  \033[0;31mThe downloaded archive does not contain a valid EterX source installation.\033[0m\n' >&2
    exit 1
  fi

  mkdir -p "$INSTALL_DIR"
  cp -a "$source/." "$INSTALL_DIR/"
  printf '  \033[0;32mSource installed at %s\033[0m\n' "$INSTALL_DIR"
}

printf '\n  \033[0;35mEterX Agent source setup\033[0m\n'
printf '  \033[0;90mFor the one-click desktop app, use the packaged installer for your platform.\033[0m\n\n'

ensure_node
install_source_archive
cd "$INSTALL_DIR"
had_env=0
[ -f '.env.local' ] && had_env=1

status 'Installing application dependencies and local workspace...'
node setup.js --auto --no-doctor

if [ "$had_env" = '0' ] && [ "${ETERX_SKIP_API:-0}" != '1' ]; then
  status 'Opening the optional API-key setup...'
  node setup.js --api
fi

printf '\n  \033[0;32mEterX source installation is ready.\033[0m\n'
